                .query_map([side], |row| row.get(3))
                .unwrap()
                .collect::<rusqlite::Result<_>>()
                .unwrap();
            assert!(query_plan.iter().any(|step| step.contains("PRIMARY KEY")));
            assert!(query_plan.iter().all(|step| !step.contains("TEMP B-TREE")));
            let actual: Vec<String> = scratch
